-- Multi-tenant core. Every tenant-owned row carries ClinicId (a GUID generated by the API,
-- so the tenant context can be set before the clinic row itself is inserted).

CREATE TABLE app.Clinic
(
    ClinicId               UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_Clinic PRIMARY KEY,
    Name                   NVARCHAR(150)    NOT NULL,
    TimeZoneId             VARCHAR(64)      NOT NULL,
    WorkweekStart          TINYINT          NOT NULL CONSTRAINT DF_Clinic_WorkweekStart DEFAULT (1)      -- 0 = Sunday ... 6 = Saturday
                                            CONSTRAINT CK_Clinic_WorkweekStart CHECK (WorkweekStart BETWEEN 0 AND 6),
    OvertimeThresholdHours DECIMAL(5,2)     NOT NULL CONSTRAINT DF_Clinic_OvertimeThreshold DEFAULT (40),
    DefaultBreakMinutes    INT              NOT NULL CONSTRAINT DF_Clinic_DefaultBreak DEFAULT (30),
    LeaveAllowanceDays     DECIMAL(5,1)     NOT NULL CONSTRAINT DF_Clinic_LeaveAllowance DEFAULT (15),
    PlanCode               VARCHAR(20)      NOT NULL CONSTRAINT DF_Clinic_Plan DEFAULT ('trial'),
    TrialEndsUtc           DATETIME2(0)     NOT NULL,
    IsDemo                 BIT              NOT NULL CONSTRAINT DF_Clinic_IsDemo DEFAULT (0),
    CreatedAtUtc           DATETIME2(0)     NOT NULL CONSTRAINT DF_Clinic_CreatedAtUtc DEFAULT (SYSUTCDATETIME())
);

-- Sign-in identity. Global (not filtered by tenant) because sign-in happens before the tenant is known.
CREATE TABLE app.UserAccount
(
    UserId       INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_UserAccount PRIMARY KEY,
    ClinicId     UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_UserAccount_Clinic REFERENCES app.Clinic (ClinicId),
    Email        NVARCHAR(256)     NOT NULL CONSTRAINT UQ_UserAccount_Email UNIQUE,
    PasswordHash NVARCHAR(400)     NOT NULL,
    CreatedAtUtc DATETIME2(0)      NOT NULL CONSTRAINT DF_UserAccount_CreatedAtUtc DEFAULT (SYSUTCDATETIME()),
    LastLoginUtc DATETIME2(0)      NULL
);

CREATE TABLE app.Location
(
    LocationId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Location PRIMARY KEY,
    ClinicId   UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_Location_Clinic REFERENCES app.Clinic (ClinicId),
    Name       NVARCHAR(100)     NOT NULL,
    Address    NVARCHAR(300)     NULL,
    IsActive   BIT               NOT NULL CONSTRAINT DF_Location_IsActive DEFAULT (1),
    CONSTRAINT UQ_Location_Name UNIQUE (ClinicId, Name)
);

CREATE TABLE app.JobTitle
(
    JobTitleId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_JobTitle PRIMARY KEY,
    ClinicId   UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_JobTitle_Clinic REFERENCES app.Clinic (ClinicId),
    Name       NVARCHAR(60)      NOT NULL,
    Role       VARCHAR(20)       NOT NULL CONSTRAINT CK_JobTitle_Role CHECK (Role IN ('owner_admin','practice_manager','clinical_staff','reception')),
    CONSTRAINT UQ_JobTitle_Name UNIQUE (ClinicId, Name)
);

CREATE TABLE app.Staff
(
    StaffId          INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Staff PRIMARY KEY,
    ClinicId         UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_Staff_Clinic REFERENCES app.Clinic (ClinicId),
    UserId           INT               NULL CONSTRAINT FK_Staff_UserAccount REFERENCES app.UserAccount (UserId),
    FirstName        NVARCHAR(60)      NOT NULL,
    LastName         NVARCHAR(60)      NOT NULL,
    Email            NVARCHAR(256)     NOT NULL,
    Phone            NVARCHAR(30)      NULL,
    Role             VARCHAR(20)       NOT NULL CONSTRAINT CK_Staff_Role CHECK (Role IN ('owner_admin','practice_manager','clinical_staff','reception')),
    JobTitleId       INT               NOT NULL CONSTRAINT FK_Staff_JobTitle REFERENCES app.JobTitle (JobTitleId),
    HomeLocationId   INT               NOT NULL CONSTRAINT FK_Staff_Location REFERENCES app.Location (LocationId),
    StartDate        DATE              NOT NULL,
    IsActive         BIT               NOT NULL CONSTRAINT DF_Staff_IsActive DEFAULT (1),
    OvertimeEligible BIT               NOT NULL CONSTRAINT DF_Staff_OvertimeEligible DEFAULT (1),
    EmploymentType   VARCHAR(10)       NOT NULL CONSTRAINT CK_Staff_EmploymentType CHECK (EmploymentType IN ('full_time','part_time')),
    CONSTRAINT UQ_Staff_Email UNIQUE (ClinicId, Email)
);

-- Invitation lookups happen before sign-in, so this table is global; only a SHA-256 hash of the token is stored.
CREATE TABLE app.Invitation
(
    InvitationId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Invitation PRIMARY KEY,
    ClinicId     UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_Invitation_Clinic REFERENCES app.Clinic (ClinicId),
    StaffId      INT               NOT NULL CONSTRAINT FK_Invitation_Staff REFERENCES app.Staff (StaffId),
    TokenHash    CHAR(64)          NOT NULL CONSTRAINT UQ_Invitation_Token UNIQUE,
    ExpiresUtc   DATETIME2(0)      NOT NULL,
    AcceptedUtc  DATETIME2(0)      NULL,
    CreatedAtUtc DATETIME2(0)      NOT NULL CONSTRAINT DF_Invitation_CreatedAtUtc DEFAULT (SYSUTCDATETIME())
);

CREATE TABLE app.ShiftDefinition
(
    ShiftDefinitionId  INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ShiftDefinition PRIMARY KEY,
    ClinicId           UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_ShiftDefinition_Clinic REFERENCES app.Clinic (ClinicId),
    Name               NVARCHAR(40)      NOT NULL,
    StartTime          TIME(0)           NOT NULL,
    EndTime            TIME(0)           NOT NULL,
    UnpaidBreakMinutes INT               NULL,
    CONSTRAINT CK_ShiftDefinition_Times CHECK (EndTime > StartTime),
    CONSTRAINT UQ_ShiftDefinition_Name UNIQUE (ClinicId, Name)
);

CREATE TABLE app.StaffWorkPattern
(
    PatternId     INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_StaffWorkPattern PRIMARY KEY,
    ClinicId      UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_StaffWorkPattern_Clinic REFERENCES app.Clinic (ClinicId),
    StaffId       INT               NOT NULL CONSTRAINT FK_StaffWorkPattern_Staff REFERENCES app.Staff (StaffId),
    EffectiveFrom DATE              NOT NULL,
    CONSTRAINT UQ_StaffWorkPattern UNIQUE (StaffId, EffectiveFrom)
);

CREATE TABLE app.StaffWorkPatternDay
(
    PatternDayId      INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_StaffWorkPatternDay PRIMARY KEY,
    ClinicId          UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_StaffWorkPatternDay_Clinic REFERENCES app.Clinic (ClinicId),
    PatternId         INT               NOT NULL CONSTRAINT FK_StaffWorkPatternDay_Pattern REFERENCES app.StaffWorkPattern (PatternId) ON DELETE CASCADE,
    Weekday           TINYINT           NOT NULL CONSTRAINT CK_StaffWorkPatternDay_Weekday CHECK (Weekday BETWEEN 0 AND 6),
    ShiftDefinitionId INT               NOT NULL CONSTRAINT FK_StaffWorkPatternDay_ShiftDefinition REFERENCES app.ShiftDefinition (ShiftDefinitionId),
    LocationId        INT               NOT NULL CONSTRAINT FK_StaffWorkPatternDay_Location REFERENCES app.Location (LocationId),
    CONSTRAINT UQ_StaffWorkPatternDay UNIQUE (PatternId, Weekday)
);

CREATE TABLE app.Shift
(
    ShiftId            INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Shift PRIMARY KEY,
    ClinicId           UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_Shift_Clinic REFERENCES app.Clinic (ClinicId),
    StaffId            INT               NOT NULL CONSTRAINT FK_Shift_Staff REFERENCES app.Staff (StaffId),
    LocationId         INT               NOT NULL CONSTRAINT FK_Shift_Location REFERENCES app.Location (LocationId),
    ShiftDate          DATE              NOT NULL,
    StartTime          TIME(0)           NOT NULL,
    EndTime            TIME(0)           NOT NULL,
    UnpaidBreakMinutes INT               NOT NULL CONSTRAINT DF_Shift_Break DEFAULT (0),
    IsPublished        BIT               NOT NULL CONSTRAINT DF_Shift_IsPublished DEFAULT (0),
    UpdatedAtUtc       DATETIME2(0)      NOT NULL CONSTRAINT DF_Shift_UpdatedAtUtc DEFAULT (SYSUTCDATETIME()),
    CONSTRAINT CK_Shift_Times CHECK (EndTime > StartTime),
    CONSTRAINT CK_Shift_Break CHECK (UnpaidBreakMinutes >= 0)
);
CREATE INDEX IX_Shift_Date ON app.Shift (ClinicId, ShiftDate) INCLUDE (StaffId, LocationId, StartTime, EndTime, IsPublished);

CREATE TABLE app.ClosedDay
(
    ClosedDayId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ClosedDay PRIMARY KEY,
    ClinicId    UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_ClosedDay_Clinic REFERENCES app.Clinic (ClinicId),
    LocationId  INT               NULL CONSTRAINT FK_ClosedDay_Location REFERENCES app.Location (LocationId), -- NULL = every location
    ClosedOn    DATE              NOT NULL,
    Name        NVARCHAR(80)      NOT NULL
);

CREATE TABLE app.CoverageRule
(
    CoverageRuleId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CoverageRule PRIMARY KEY,
    ClinicId       UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_CoverageRule_Clinic REFERENCES app.Clinic (ClinicId),
    LocationId     INT               NOT NULL CONSTRAINT FK_CoverageRule_Location REFERENCES app.Location (LocationId),
    JobTitleId     INT               NOT NULL CONSTRAINT FK_CoverageRule_JobTitle REFERENCES app.JobTitle (JobTitleId),
    Weekday        TINYINT           NOT NULL CONSTRAINT CK_CoverageRule_Weekday CHECK (Weekday BETWEEN 0 AND 6),
    MinHeadcount   INT               NOT NULL CONSTRAINT CK_CoverageRule_Min CHECK (MinHeadcount >= 0),
    CONSTRAINT UQ_CoverageRule UNIQUE (LocationId, JobTitleId, Weekday)
);

CREATE TABLE app.CredentialType
(
    CredentialTypeId INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CredentialType PRIMARY KEY,
    ClinicId         UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_CredentialType_Clinic REFERENCES app.Clinic (ClinicId),
    Name             NVARCHAR(80)      NOT NULL,
    BlocksScheduling BIT               NOT NULL,
    CONSTRAINT UQ_CredentialType_Name UNIQUE (ClinicId, Name)
);

CREATE TABLE app.CredentialTypeJobTitle
(
    ClinicId         UNIQUEIDENTIFIER NOT NULL CONSTRAINT FK_CredentialTypeJobTitle_Clinic REFERENCES app.Clinic (ClinicId),
    CredentialTypeId INT              NOT NULL CONSTRAINT FK_CredentialTypeJobTitle_Type REFERENCES app.CredentialType (CredentialTypeId),
    JobTitleId       INT              NOT NULL CONSTRAINT FK_CredentialTypeJobTitle_JobTitle REFERENCES app.JobTitle (JobTitleId),
    CONSTRAINT PK_CredentialTypeJobTitle PRIMARY KEY (CredentialTypeId, JobTitleId)
);

CREATE TABLE app.Credential
(
    CredentialId     INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Credential PRIMARY KEY,
    ClinicId         UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_Credential_Clinic REFERENCES app.Clinic (ClinicId),
    StaffId          INT               NOT NULL CONSTRAINT FK_Credential_Staff REFERENCES app.Staff (StaffId),
    CredentialTypeId INT               NOT NULL CONSTRAINT FK_Credential_Type REFERENCES app.CredentialType (CredentialTypeId),
    ExpiresOn        DATE              NOT NULL
);

CREATE TABLE app.LeaveRequest
(
    LeaveRequestId   INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_LeaveRequest PRIMARY KEY,
    ClinicId         UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_LeaveRequest_Clinic REFERENCES app.Clinic (ClinicId),
    StaffId          INT               NOT NULL CONSTRAINT FK_LeaveRequest_Staff REFERENCES app.Staff (StaffId),
    StartDate        DATE              NOT NULL,
    EndDate          DATE              NOT NULL,
    FirstDayHalf     BIT               NOT NULL CONSTRAINT DF_LeaveRequest_FirstDayHalf DEFAULT (0),
    LastDayHalf      BIT               NOT NULL CONSTRAINT DF_LeaveRequest_LastDayHalf DEFAULT (0),
    LeaveType        VARCHAR(10)       NOT NULL CONSTRAINT CK_LeaveRequest_Type CHECK (LeaveType IN ('annual','sick','other')),
    DaysCounted      DECIMAL(4,1)      NOT NULL,
    Note             NVARCHAR(500)     NULL,
    Status           VARCHAR(10)       NOT NULL CONSTRAINT CK_LeaveRequest_Status CHECK (Status IN ('pending','approved','rejected')),
    DecidedByStaffId INT               NULL CONSTRAINT FK_LeaveRequest_DecidedBy REFERENCES app.Staff (StaffId),
    DecisionComment  NVARCHAR(500)     NULL,
    CreatedAtUtc     DATETIME2(0)      NOT NULL CONSTRAINT DF_LeaveRequest_CreatedAtUtc DEFAULT (SYSUTCDATETIME()),
    DecidedAtUtc     DATETIME2(0)      NULL,
    CONSTRAINT CK_LeaveRequest_Dates CHECK (EndDate >= StartDate)
);

CREATE TABLE app.AttendanceRecord
(
    AttendanceId       INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_AttendanceRecord PRIMARY KEY,
    ClinicId           UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_AttendanceRecord_Clinic REFERENCES app.Clinic (ClinicId),
    StaffId            INT               NOT NULL CONSTRAINT FK_AttendanceRecord_Staff REFERENCES app.Staff (StaffId),
    ShiftId            INT               NULL CONSTRAINT FK_AttendanceRecord_Shift REFERENCES app.Shift (ShiftId) ON DELETE SET NULL,
    LocationId         INT               NOT NULL CONSTRAINT FK_AttendanceRecord_Location REFERENCES app.Location (LocationId),
    ClockInUtc         DATETIME2(0)      NOT NULL CONSTRAINT DF_AttendanceRecord_ClockIn DEFAULT (SYSUTCDATETIME()),
    ClockOutUtc        DATETIME2(0)      NULL,
    UnpaidBreakMinutes INT               NOT NULL,
    IsUnscheduled      BIT               NOT NULL,
    UnscheduledConfirmedByStaffId INT    NULL CONSTRAINT FK_AttendanceRecord_ConfirmedBy REFERENCES app.Staff (StaffId),
    CorrectedByStaffId INT               NULL CONSTRAINT FK_AttendanceRecord_CorrectedBy REFERENCES app.Staff (StaffId),
    CorrectionNote     NVARCHAR(300)     NULL
);
-- One open record per person at a time.
CREATE UNIQUE INDEX UX_AttendanceRecord_Open ON app.AttendanceRecord (StaffId) WHERE ClockOutUtc IS NULL;

CREATE TABLE app.ScheduleOverride
(
    OverrideId          INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ScheduleOverride PRIMARY KEY,
    ClinicId            UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_ScheduleOverride_Clinic REFERENCES app.Clinic (ClinicId),
    ShiftId             INT               NOT NULL CONSTRAINT FK_ScheduleOverride_Shift REFERENCES app.Shift (ShiftId) ON DELETE CASCADE,
    CredentialTypeId    INT               NOT NULL CONSTRAINT FK_ScheduleOverride_CredentialType REFERENCES app.CredentialType (CredentialTypeId),
    OverriddenByStaffId INT               NOT NULL CONSTRAINT FK_ScheduleOverride_Staff REFERENCES app.Staff (StaffId),
    Reason              NVARCHAR(300)     NOT NULL,
    OverriddenAtUtc     DATETIME2(0)      NOT NULL CONSTRAINT DF_ScheduleOverride_At DEFAULT (SYSUTCDATETIME())
);

CREATE TABLE app.Notification
(
    NotificationId   INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_Notification PRIMARY KEY,
    ClinicId         UNIQUEIDENTIFIER  NOT NULL CONSTRAINT FK_Notification_Clinic REFERENCES app.Clinic (ClinicId),
    RecipientStaffId INT               NOT NULL CONSTRAINT FK_Notification_Staff REFERENCES app.Staff (StaffId),
    Type             VARCHAR(40)       NOT NULL,
    Message          NVARCHAR(300)     NOT NULL,
    IsRead           BIT               NOT NULL CONSTRAINT DF_Notification_IsRead DEFAULT (0),
    CreatedAtUtc     DATETIME2(0)      NOT NULL CONSTRAINT DF_Notification_CreatedAtUtc DEFAULT (SYSUTCDATETIME())
);
CREATE INDEX IX_Notification_Recipient ON app.Notification (RecipientStaffId, IsRead);

CREATE TABLE audit.AuditLogEntry
(
    AuditId    BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_AuditLogEntry PRIMARY KEY,
    ClinicId   UNIQUEIDENTIFIER     NOT NULL,
    AtUtc      DATETIME2(0)         NOT NULL CONSTRAINT DF_AuditLogEntry_At DEFAULT (SYSUTCDATETIME()),
    UserId     INT                  NULL,
    Action     VARCHAR(10)          NOT NULL,
    EntityName VARCHAR(40)          NOT NULL,
    EntityId   NVARCHAR(40)         NOT NULL,
    OldValue   NVARCHAR(MAX)        NULL,
    NewValue   NVARCHAR(MAX)        NULL
);
CREATE INDEX IX_AuditLogEntry_Clinic ON audit.AuditLogEntry (ClinicId, AtUtc DESC);
GO
